CREATE TABLE IF NOT EXISTS lxbg_mod_adserv_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,channel_name VARCHAR(80) NOT NULL DEFAULT '#lxbg',message VARCHAR(500) NOT NULL,interval_minutes INT UNSIGNED NOT NULL DEFAULT 30,enabled TINYINT(1) NOT NULL DEFAULT 1,last_sent_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(enabled,last_sent_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
